@Composable fun LibraryRoute(vm:LibraryViewModel= hiltViewModel()){val s by vm.state.collectAsState();val snack=remember{SnackbarHostState()};LaunchedEffect(s.message){s.message?.let{snack.showSnackbar(it);vm.consume()}};LibraryScreen(s,snack,vm)}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun LibraryScreen(s:LibraryUiState,snack:SnackbarHostState,vm:LibraryViewModel){var remove by remember{mutableStateOf<LibraryMaterial?>(null)};val browser=LocalUriHandler.current;Scaffold(containerColor=AxeCloudThemeTokens.Canvas,snackbarHost={SnackbarHost(snack)},floatingActionButton={if(!s.isFilho)FloatingActionButton(vm::openUpload,containerColor=Color(0xFFD7B75B),contentColor=Color(0xFF282116),shape=RoundedCornerShape(18.dp)){Icon(Icons.Outlined.UploadFile,"Publicar PDF")}}){p->LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(horizontal=18.dp,vertical=16.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{LibraryHero(s)};item{OutlinedTextField(s.query,vm::query,Modifier.fillMaxWidth(),singleLine=true,leadingIcon={Icon(Icons.Outlined.Search,null)},placeholder={Text("Buscar no acervo")},shape=RoundedCornerShape(18.dp))};item{Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){s.categories.forEach{c->FilterChip(s.category==c,{vm.category(c)},label={Text(c)})}}};when{s.loading->item{Box(Modifier.fillMaxWidth().padding(50.dp),contentAlignment=Alignment.Center){CircularProgressIndicator(color=Color(0xFF5D4827))}};s.error!=null&&s.materials.isEmpty()->item{Text(s.error,color=MaterialTheme.colorScheme.error)};s.visible.isEmpty()->item{EmptyLibrary()};else->items(s.visible,key={it.id}){m->MaterialCard(m,s.isFilho,s.actionId==m.id,{if(m.url.isNotBlank())browser.openUri(m.url)},{remove=m})}};item{Spacer(Modifier.height(80.dp))}}};if(s.uploadOpen)UploadSheet(s.uploading,s.error,vm::closeUpload,vm::upload);remove?.let{m->AlertDialog(onDismissRequest={remove=null},title={Text("Excluir ${m.title}?")},text={Text("O PDF privado e seu registro serão removidos.")},confirmButton={Button({remove=null;vm.delete(m)},colors=ButtonDefaults.buttonColors(containerColor=MaterialTheme.colorScheme.error)){Text("Excluir")}},dismissButton={TextButton({remove=null}){Text("Cancelar")}})}}
@Composable private fun LibraryHero(s:LibraryUiState)=Surface(shape=RoundedCornerShape(27.dp),color=Color(0xFF302A21)){Column(Modifier.fillMaxWidth().padding(22.dp)){Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(14.dp),color=Color(0xFFD7B75B)){Icon(Icons.Outlined.AutoStories,null,Modifier.padding(11.dp),tint=Color(0xFF282116))};Column(Modifier.padding(start=12.dp)){Text("MEMÓRIA E FUNDAMENTO",color=Color(0xFFD7B75B),fontSize=10.sp,fontWeight=FontWeight.Black,letterSpacing=1.sp);Text(if(s.isFilho)"Meus estudos" else "Biblioteca da casa",color=Color.White,fontSize=26.sp,fontWeight=FontWeight.Black)}};Spacer(Modifier.height(17.dp));Text("${s.materials.size} materiais preservados · ${s.materials.map{it.category}.distinct().size} coleções",color=Color.White.copy(.68f),fontSize=12.sp)}}
@Composable private fun MaterialCard(m:LibraryMaterial,filho:Boolean,busy:Boolean,open:()->Unit,delete:()->Unit)=Surface(Modifier.fillMaxWidth().clickable(onClick=open),shape=RoundedCornerShape(19.dp),color=Color.White,border=BorderStroke(1.dp,AxeCloudThemeTokens.Outline)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(52.dp).background(Color(0xFFD7B75B).copy(.14f),RoundedCornerShape(15.dp)),contentAlignment=Alignment.Center){Icon(Icons.Outlined.PictureAsPdf,null,tint=Color(0xFF6C542E))};Column(Modifier.weight(1f).padding(horizontal=11.dp)){Text(m.category.uppercase(),color=Color(0xFF8A6D36),fontSize=9.sp,fontWeight=FontWeight.Black,letterSpacing=.7.sp);Text(m.title,color=AxeCloudThemeTokens.Ink,fontWeight=FontWeight.ExtraBold,maxLines=2,overflow=TextOverflow.Ellipsis);Text("Toque para abrir o PDF",color=AxeCloudThemeTokens.Muted,fontSize=10.sp)};if(!filho)IconButton(delete){if(busy)CircularProgressIndicator(Modifier.size(18.dp),strokeWidth=2.dp)else Icon(Icons.Outlined.DeleteOutline,"Excluir")};Icon(Icons.Outlined.OpenInNew,null,tint=Color(0xFF6C542E))}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun UploadSheet(uploading:Boolean,error:String?,dismiss:()->Unit,upload:(Uri,String,String)->Unit){var title by rememberSaveable{mutableStateOf("")};var category by rememberSaveable{mutableStateOf("Cantigas")};var uri by remember{mutableStateOf<Uri?>(null)};val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri=it};ModalBottomSheet(onDismissRequest=dismiss,containerColor=AxeCloudThemeTokens.Canvas){Column(Modifier.navigationBarsPadding().padding(horizontal=20.dp).padding(bottom=24.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){Text("Publicar estudo",color=AxeCloudThemeTokens.Ink,fontSize=24.sp,fontWeight=FontWeight.Black);OutlinedTextField(title,{title=it},Modifier.fillMaxWidth(),label={Text("Título")},shape=RoundedCornerShape(15.dp));Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("Cantigas","História","Ervas","Orixás","Fundamentos").forEach{c->FilterChip(category==c,{category=c},label={Text(c)})}};OutlinedButton({picker.launch(arrayOf("application/pdf"))},Modifier.fillMaxWidth().height(52.dp)){Icon(Icons.Outlined.AttachFile,null);Spacer(Modifier.width(6.dp));Text(if(uri==null)"Escolher PDF" else "PDF selecionado")};error?.let{Text(it,color=MaterialTheme.colorScheme.error)};Button({uri?.let{upload(it,title,category)}},Modifier.fillMaxWidth().height(52.dp),enabled=!uploading&&uri!=null&&title.isNotBlank(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF302A21))){if(uploading)CircularProgressIndicator(Modifier.size(19.dp),strokeWidth=2.dp,color=Color.White)else Text("Publicar na biblioteca")}}}}
@Composable private fun EmptyLibrary()=Surface(shape=RoundedCornerShape(20.dp),color=Color.White,border=BorderStroke(1.dp,AxeCloudThemeTokens.Outline)){Column(Modifier.fillMaxWidth().padding(28.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Outlined.AutoStories,null,Modifier.size(38.dp),tint=Color(0xFF6C542E));Text("O acervo está aguardando",color=AxeCloudThemeTokens.Ink,fontWeight=FontWeight.Black);Text("Os materiais liberados pela casa aparecerão aqui.",color=AxeCloudThemeTokens.Muted,fontSize=11.sp)}}
